using System;
using System.Linq;
using System.Collections.Generic;
using System.Reflection;
using System.Text.Json;
using Deception.Core;
using Deception.PolyModAdapter;
using K=Deception.Core.NativeExchangeKind;
namespace Deception.Tests{
 public static partial class SupportTests{
  static int Assertions;static readonly List<string> Cases=new();static void Check(bool b,string why){Assertions++;if(!b)throw new Exception(why);}static void Test(string n,Action a){try{a();Cases.Add(n);}catch(Exception e){throw new Exception(n,e);}}
  sealed record Rig(GameState S,UnitState C,UnitState T);
  static LedgerAppearance Art(string f,ushort hp=60,ushort max=100,params string[] effects)=>new(f,new("Elyrion","DarkElf"),new("Imperius","Default"),new("Elyrion","DarkElf"),4,hp,max,false,ApparentConcealment.Visible,-1,effects.OrderBy(x=>x,StringComparer.Ordinal).ToArray());
  static NativeIdentityLedger Ledger(Rig r){var s=NativeGameStateEnvelope.Get(r.S)!;return NativeIdentityLedgerCodec.Decode(s.Bytes(),s.Revision);}
  static void Edit(Rig r,Func<LedgerUnit,LedgerUnit> f){var s=NativeGameStateEnvelope.Get(r.S)!;NativeGameStateEnvelope.Set(r.S,s.Revision,NativeIdentityLedgerCodec.Encode(Ledger(r) with{Units=Ledger(r).Units.Select(f).ToArray()},s.Revision));}
  static LedgerUnit Row(Rig r,uint id=2)=>Ledger(r).Units.Single(x=>x.NativeId==id);
  static Rig Start(string form="mindbender",bool mimic=true,bool independent=true){
   Fault.At="";GameManager.Client=new();GameManager.Viewing=true;RecruitmentHooks.Reset();NativeGameStateEnvelope.Frames.Clear();NativeFeignSupport.Clear();NativeFeignSupportReaction.Clear();VisualEvents.Played.Clear();VisualEvents.Waiting.Clear();VisualEvents.DoubleCallback=VisualEvents.Throw=VisualEvents.Delay=false;NativeRegroupSession.Faults.Clear();NativeRegroupSession.Admitted=true;
   var s=new GameState{CurrentUnitId=3};GameManager.GameState=s;NativeRegroupSession.Owned=s;
   UnitState Unit(uint id,string name,ushort hp,int x){var d=RecruitmentHooks.Definitions[name];var u=new UnitState{id=id,type=d.type,UnitData=d,health=hp,coordinates=new(x,0)};s.Map.Tiles.Add(new TileData{unit=u,coordinates=u.coordinates});return u;}
   var c=Unit(1,mimic?RecruitmentCatalog.Variant(form):"warrior",mimic?(ushort)10:(ushort)100,0);var t=Unit(2,"warrior",100,1);
   var units=new[]{new LedgerUnit(2,1,true,mimic?LedgerActualKind.Mimic:LedgerActualKind.Genuine,true,Art(form,100),PaidInvestmentKind.Known,3),new LedgerUnit(3,2,true,LedgerActualKind.Genuine,independent,independent?Art("giant",60,400):null,PaidInvestmentKind.Known,2)};
   var l=new NativeIdentityLedger(Guid.Parse("ba6b487b-a680-4083-9cae-1df97b1d3bc6"),5,1,units,Array.Empty<LedgerReceipt>());NativeGameStateEnvelope.Set(s,0,NativeIdentityLedgerCodec.Encode(l,0));GameManager.LocalPlayer=s.Player;MapRenderer.Current=new();foreach(var tile in s.Map.Tiles)MapRenderer.Current.Tiles[tile.coordinates.ToString()]=new Tile{Data=tile,unit=tile.unit is null?null:new Unit{UnitState=tile.unit}};return new(s,c,t);
  }
  static NativeExchangeIntent Offer(Rig r,K k=K.FeignHeal){Check(NativeFeignSupport.TryOffer(r.S,1,k,out var i,out var why),why);return i!;}
  static void Commit(Rig r,NativeExchangeIntent i){Check(NativeFeignSupport.TryCommit(r.S,i,out var result,out var why),why);Check(result is {AlreadyCommitted:false},"new action committed once");}
  static string Truth(Rig r)=>TransportStateDump.Dump(r.S);
  static string Body(UnitState u)=>string.Join("|",u.Pointer,u.id,u.type,u.UnitData.Pointer,u.UnitData.health,u.owner,u.health,u.promotionLevel,u.xp,u.createdTurn,u.home,u.coordinates,u.moved,u.attacked,u.effects.Pointer,string.Join(",",Native.Items(u.effects)),u.passengerUnit?.Pointer);
  static void Scope(Rig r,string owner,Action body){var m=typeof(SupportTests).Assembly.GetType(owner)!.GetMethod("Execute")!;NativeFeignSupportEffects.BeforeScope(r.S,m,out var scope);body();var error=NativeFeignSupportEffects.FinishScope(null,scope);if(error!=null)throw error;if(owner=="EndTurnCommand")NativeFeignSupportEffects.Flush(r.S);}
  public static int Run(){try{
   foreach(bool mimic in new[]{false,true})foreach(string form in new[]{"mindbender","shaman"})Test($"fake-area-{form}-mimic-{mimic}",()=>{
    var r=Start(form,mimic);var kind=form=="mindbender"?K.FeignHeal:K.FeignSwarm;var beforeType=r.C.type;var effects=r.T.effects;var data=r.T.UnitData;var before=Truth(r);var i=Offer(r,kind);
    Check(Truth(r)==before,"offer pure");Commit(r,i);var a=Row(r).Appearance!;Check(kind==K.FeignHeal?a.Health==100:a.Effects.Contains("Swift"),"apparent change represented");Check(r.C.type==beforeType&&r.T.health==100&&ReferenceEquals(effects,r.T.effects)&&ReferenceEquals(data,r.T.UnitData),"real HP/form/effects/profile unchanged");Check(r.C.moved&&r.C.attacked&&!r.T.moved&&!r.T.attacked&&r.S.Stars==21,"one caster allowance and no other costs");Check(Row(r,1).Appearance!.Form==form,"source disguise retained");
    string after=Truth(r);var payload=NativeGameStateEnvelope.Get(r.S)!.Bytes();Check(NativeFeignSupport.TryCommit(r.S,i,out var duplicate,out var reason)&&duplicate!.AlreadyCommitted,reason);Check(Truth(r)==after&&payload.SequenceEqual(NativeGameStateEnvelope.Get(r.S)!.Bytes()),"duplicate no flags/status/cue replay");
   });
   foreach(K kind in new[]{K.FeignHeal,K.FeignBoost,K.FeignSwarm})foreach(bool failed in new[]{false,true})Test("mimic-dash-support-"+kind+"-rollback-"+failed,()=>{
    var r=Start(kind==K.FeignHeal?"mindbender":"shaman");r.C.moved=true;var before=Truth(r);var frame=NativeGameStateEnvelope.Get(r.S)!.Bytes();var i=Offer(r,kind);Check(Truth(r)==before,"post-move offer is read-only");
    if(failed){Fault.At="ledger";Check(!NativeFeignSupport.TryCommit(r.S,i,out _,out _),"publication failure rejected");Check(Truth(r)==before&&frame.SequenceEqual(NativeGameStateEnvelope.Get(r.S)!.Bytes()),"failure cannot refund prior movement or change recipient");}
    else {Commit(r,i);Check(r.C.moved&&r.C.attacked&&!r.T.moved&&!r.T.attacked,"Dash retains move and spends only caster action");Check(!NativeFeignSupport.TryOffer(r.S,1,kind,out _,out _),"spent Mimic cannot feign twice");}
   });
   foreach(string species in new[]{SpyCatalog.Id,SpyCatalog.AquarionId})foreach(bool failed in new[]{false,true})Test("spy-feign-reveals-"+species+"-rollback-"+failed,()=>{
    var r=Start(mimic:false);r.C.type=Enum.Parse<Polytopia.Data.UnitData.Type>(species);r.C.UnitData=RecruitmentHooks.Definitions[species];r.C.effects.Add(UnitEffect.Invisible);r.C.effects.Add(UnitEffect.Poisoned);
    Edit(r,x=>x.NativeId==1?x with{Appearance=x.Appearance! with{Concealment=ApparentConcealment.Hidden,Effects=new[]{"Invisible"}}}:x);
    var effects=r.C.effects;string before=Truth(r);var frame=NativeGameStateEnvelope.Get(r.S)!.Bytes();var i=Offer(r);Check(ReferenceEquals(effects,r.C.effects)&&Truth(r)==before,"offering cannot reveal Spy");
    if(failed){Fault.At="ledger";Check(!NativeFeignSupport.TryCommit(r.S,i,out _,out _),"publication fault rejected");Check(ReferenceEquals(effects,r.C.effects)&&Truth(r)==before&&frame.SequenceEqual(NativeGameStateEnvelope.Get(r.S)!.Bytes()),"failure restores true and apparent concealment exactly");}
    else {Commit(r,i);Check(r.C.effects.Contains(UnitEffect.Poisoned)&&!r.C.effects.Contains(UnitEffect.Invisible)&&effects.Contains(UnitEffect.Invisible),"active feint reveals only real Spy, without mutating prior effect list");Check(Row(r,1).Appearance is {Concealment:ApparentConcealment.Visible} source&&!source.Effects.Contains("Invisible"),"Spy disguise also reveals on active feint");var after=Truth(r);Check(NativeFeignSupport.TryCommit(r.S,i,out var duplicate,out _)&&duplicate!.AlreadyCommitted&&Truth(r)==after,"duplicate cannot apply reveal or action twice");}
   });
   Test("moved-mimic-cannot-recover-via-apparent-wound",()=>{var r=Start();r.C.moved=true;Edit(r,x=>x.NativeId==1?x with{Appearance=x.Appearance! with{Health=50}}:x);bool available=false;NativeFeignSupportEffects.CanRecover(r.C,r.S,ref available);Check(!available,"Dash must not reopen full-turn Recover");});
   foreach(K kind in new[]{K.FeignBoost,K.FeignSwarm})Test("boost-no-mobility-"+kind,()=>{var r=Start("shaman");r.T.moved=r.T.attacked=true;Commit(r,Offer(r,kind));Check(Row(r).Appearance!.Effects.SequenceEqual(new[]{"Swift"}),"native current boost status");Check(r.T.moved&&r.T.attacked&&r.T.effects.Count==0,"no new actual movement or status");});
   foreach(string form in new[]{"bombership","juggernaut"})Test("heal-ordinary-vessel-independent-cargo-"+form,()=>{
    var r=Start();var passenger=Art("giant",275,400);var vessel=Art(form,330,400) with{Passenger=passenger};
    Edit(r,row=>row.NativeId==2?row with{Appearance=vessel}:row);string before=Body(r.T);Commit(r,Offer(r));var healed=Row(r).Appearance!;
    Check(healed.Health==370&&healed.Maximum==400&&NativeExchangeIntentCodec.AppearanceFingerprint(healed.Passenger!).SequenceEqual(NativeExchangeIntentCodec.AppearanceFingerprint(passenger)),"Feign Heal must retain passenger-derived maximum and independent cargo wound");
    Check(Body(r.T)==before&&r.T.health==100,"Feign naval healing never changes the true unit");
    Check(RecruitmentHooks.Definitions[form].unitAbilities.Contains(UnitAbility.Stiff)&&!RecruitmentHooks.Definitions[form].unitAbilities.Contains(UnitAbility.Protect),"Ordinary captured boat has Stiff38 without Protect39");
   });
   Test("unmasked-stat-only-overlay",()=>{var r=Start("shaman",independent:false);Commit(r,Offer(r,K.FeignSwarm));Check(Row(r).Independent&&Row(r).Appearance!.Form=="warrior"&&Row(r).Appearance!.Health==100,"unmasked recipient has same form and apparent status");Check(r.T.type.ToString()=="warrior"&&r.T.health==100,"native untouched");});
   foreach(bool poison in new[]{false,true})foreach(bool frozen in new[]{false,true})Test($"heal-independent-cleanse-{poison}-{frozen}",()=>{var r=Start();r.T.effects.Add(UnitEffect.Poisoned);r.T.effects.Add(UnitEffect.Frozen);var old=r.T.effects;Edit(r,x=>x.NativeId==2?x with{Appearance=Art("warrior",80,100,(poison?new[]{"Poisoned","Charmed"}:Array.Empty<string>()).Concat(frozen?new[]{"Frozen"}:Array.Empty<string>()).ToArray())}:x);Commit(r,Offer(r));var a=Row(r).Appearance!;Check(a.Health==(poison?80:100)&&!a.Effects.Contains("Poisoned")&&!a.Effects.Contains("Charmed"),"cleanse versus HP independently");Check(a.Effects.Contains("Frozen")==frozen,"native Heal does not cure freeze");Check(ReferenceEquals(old,r.T.effects)&&old.Contains(UnitEffect.Poisoned)&&old.Contains(UnitEffect.Frozen),"no true cure");});
   foreach(int owner in new[]{0,1,2})Test("removed-feign-recover-never-offered-"+owner,()=>{var r=Start();Edit(r,x=>x.NativeId==1?x with{Appearance=Art("warrior",50)}:x);r.S.Map.Tiles[0].owner=(byte)owner;var before=Truth(r);var bytes=NativeGameStateEnvelope.Get(r.S)!.Bytes();Check(!NativeFeignSupport.TryOffer(r.S,1,K.FeignRecover,out _,out var why)&&why.Contains("no longer available"),"Removed recovery still offered");Check(Truth(r)==before&&bytes.SequenceEqual(NativeGameStateEnvelope.Get(r.S)!.Bytes()),"Removed offer changed state");});
   Test("removed-feign-recover-forged-command-rejected",()=>{var r=Start();var old=Offer(r) with{Kind=K.FeignRecover};var bytes=NativeGameStateEnvelope.Get(r.S)!.Bytes();string truth=Truth(r);Check(!NativeFeignSupport.TryPlan(r.S,old,out _,out var why)&&why.Contains("no longer available"),"Removed kind accepted by plan");Check(!NativeFeignSupport.TryCommit(r.S,old,out _,out _)&&bytes.SequenceEqual(NativeGameStateEnvelope.Get(r.S)!.Bytes())&&Truth(r)==truth,"Removed kind executed or consumed action");});
   Test("historical-feign-recover-receipt-remains-idempotent",()=>{var r=Start();var old=Offer(r) with{Kind=K.FeignRecover};var ledger=Ledger(r);var receipt=new LedgerReceipt(old.Sequence,NativeExchangeIntentCodec.Operation(old.Sequence),NativeExchangeIntentCodec.Fingerprint(old),0,1,new[]{old.Initiator.LogicalId});NativeGameStateEnvelope.Set(r.S,1,NativeIdentityLedgerCodec.Encode(ledger with{NextSequence=2,Receipts=new[]{receipt}},1));var bytes=NativeGameStateEnvelope.Get(r.S)!.Bytes();string truth=Truth(r);Check(NativeFeignSupport.IsKind(K.FeignRecover)&&NativeExchangeIntentCodec.Decode(NativeExchangeIntentCodec.Encode(old)).Kind==K.FeignRecover,"Historical kind or wire format was removed");Check(NativeFeignSupport.TryCommit(r.S,old,out var result,out _)&&result!.AlreadyCommitted&&bytes.SequenceEqual(NativeGameStateEnvelope.Get(r.S)!.Bytes())&&Truth(r)==truth,"Historical acknowledged action replayed or corrupted ledger");});
   foreach(string bad in new[]{"moved","attacked","frozen","foreign","dead","linked","follower","unexplored","ended","wrong-turn","wrong-epoch","stale-ledger","wrong-tile","not-owned","wrong-ability","apparent-frozen"})Test("denial-"+bad,()=>{var r=Start(mimic:bad!="moved");var i=Offer(r);switch(bad){case "moved":r.C.moved=true;break;case "attacked":r.C.attacked=true;break;case "frozen":r.C.effects.Add(UnitEffect.Frozen);break;case "foreign":r.C.owner=2;break;case "dead":r.C.health=0;break;case "linked":r.C.leader=2;break;case "follower":r.C.follower=2;break;case "unexplored":r.S.Map.Tiles[0].Explored=false;break;case "ended":r.S.CurrentState=GameState.State.Ended;break;case "wrong-turn":r.S.CurrentTurn++;break;case "wrong-epoch":i=i with{Epoch=Guid.NewGuid()};break;case "stale-ledger":Edit(r,x=>x.NativeId==2?x with{Appearance=x.Appearance! with{Health=80}}:x);break;case "wrong-tile":r.C.coordinates=new(2,2);break;case "not-owned":NativeRegroupSession.Admitted=false;break;case "wrong-ability":i=i with{Kind=K.FeignSwarm};break;case "apparent-frozen":Edit(r,x=>x.NativeId==1?x with{Appearance=x.Appearance! with{Effects=new[]{"Frozen"}}}:x);break;}var before=Truth(r);var payload=NativeGameStateEnvelope.Get(r.S)!.Bytes();Check(!NativeFeignSupport.TryCommit(r.S,i,out _,out _),"invalid action denied");Check(before==Truth(r)&&payload.SequenceEqual(NativeGameStateEnvelope.Get(r.S)!.Bytes()),"rejection is pure");});
   foreach(string status in new[]{"Swift","Boosted"})Test("cannot-stack-"+status,()=>{var r=Start("shaman");Edit(r,x=>x.NativeId==2?x with{Appearance=x.Appearance! with{Effects=new[]{status}}}:x);Check(!NativeFeignSupport.TryOffer(r.S,1,K.FeignSwarm,out _,out _),"already apparent buff excluded");});
   foreach(string target in new[]{"foreign","rogue","leader","far"})Test("recipient-excluded-"+target,()=>{var r=Start();if(target=="foreign")r.T.owner=2;if(target=="rogue")Edit(r,x=>x.NativeId==2?x with{Rogue=new(2,1,4)}:x);if(target=="leader")r.T.leader=5;if(target=="far"){r.T.coordinates=new(3,3);r.S.Map.Tiles[1].coordinates=r.T.coordinates;}Check(!NativeFeignSupport.TryOffer(r.S,1,K.FeignHeal,out _,out _),"recipient outside permanent owner/native range rules");});
   Test("rogue-caster-supports-commanders-permanent-unit",()=>{var r=Start();Edit(r,x=>x.NativeId==1?x with{Rogue=new(2,1,4)}:x);Commit(r,Offer(r));Check(Row(r).Appearance!.Health==100&&Row(r,1).Rogue!.Owner==2,"commander recipient only, remembered owner unchanged");});
   Test("publish-failure-atomic",()=>{var r=Start();var i=Offer(r);string before=Truth(r);byte[] frame=NativeGameStateEnvelope.Get(r.S)!.Bytes();Fault.At="ledger";Check(!NativeFeignSupport.TryCommit(r.S,i,out _,out _),"publish failure caught");Check(Truth(r)==before&&frame.SequenceEqual(NativeGameStateEnvelope.Get(r.S)!.Bytes()),"exact native flags and frame restored");});
   Test("real-heal-independent-full-and-wounded",()=>{var r=Start();var action=new HealAction{Coordinates=r.T.coordinates,FixedHealAmount=40};NativeDisguiseLifecycle.BeforeHeal(action,r.S,out var h);action.HealAmount=0;NativeDisguiseLifecycle.AfterHeal(action,r.S,h);Check(Row(r).Appearance!.Health==100&&r.T.health==100,"true-full heal independently grows apparent HP");});
   Test("real-recover-clamps-apparent-without-true-wound",()=>{var r=Start();var action=new HealAction{Coordinates=r.T.coordinates};NativeDisguiseLifecycle.BeforeHeal(action,r.S,out var h);NativeDisguiseLifecycle.AfterHeal(action,r.S,h);Check(Row(r).Appearance!.Health==100&&r.T.health==100,"represented territory recovery not capped by actual wound");});
   Test("real-heal-true-poison-app-healthy",()=>{var r=Start();r.T.effects.Add(UnitEffect.Poisoned);var action=new HealAction{Coordinates=r.T.coordinates,FixedHealAmount=40};NativeDisguiseLifecycle.BeforeHeal(action,r.S,out var h);r.T.effects.Remove(UnitEffect.Poisoned);NativeDisguiseLifecycle.AfterHeal(action,r.S,h);Check(Row(r).Appearance!.Health==100,"independent apparent normal heal even when actual operation cleaned poison");});
   Test("native-heal-roster-includes-apparent-only-wound",()=>{var r=Start();object list=new Il2CppSystem.Collections.Generic.List<TileData>();NativeFeignSupportEffects.HealOptions(r.S.Map.Tiles[0],1,r.S,false,ref list);Check(Native.Items(list).Count()==1&&ReferenceEquals(Native.Items(list).Single(),r.S.Map.Tiles[1]),"false wound eligible for native real heal target");});
   foreach(bool heal in new[]{true,false})Test("native-recipient-rogue-filter-"+heal,()=>{var r=Start();Edit(r,x=>x.NativeId==2?x with{Rogue=new(2,1,4)}:x);var values=new Il2CppSystem.Collections.Generic.List<TileData>();values.Add(r.S.Map.Tiles[1]);object list=values;if(heal)NativeFeignSupportEffects.HealOptions(r.S.Map.Tiles[0],1,r.S,false,ref list);else NativeFeignSupportEffects.BoostOptions(r.S.Map.Tiles[0],1,r.S,ref list);Check(!Native.Items(list).Any()&&values.Count==1,"native query result cloned and Rogue filtered");});
   Test("native-recover-apparent-only-and-Rogue",()=>{var r=Start();bool result=false;NativeFeignSupportEffects.CanRecover(r.T,r.S,ref result);Check(result,"apparent wound opens recovery");Edit(r,x=>x.NativeId==2?x with{Rogue=new(2,1,4)}:x);NativeFeignSupportEffects.CanRecover(r.T,r.S,ref result);Check(!result,"Rogue cannot receive own recovery");});
   foreach(string name in new[]{"Poisoned","Frozen","Boosted","Swift"})Test("status-copies-native-event-"+name,()=>{var r=Start();Scope(r,"BoostAction",()=>NativeFeignSupportEffects.Added(r.T,Enum.Parse<UnitEffect>(name)));Check(Row(r).Appearance!.Effects.Contains(name),"apparent native event mirrored");Check(r.T.effects.Count==0,"observer does not write native status");});
   Test("no-status-sync-outside-authorized-scope",()=>{var r=Start();NativeFeignSupportEffects.Added(r.T,UnitEffect.Poisoned);Check(Row(r).Appearance!.Effects.Length==0,"query or unknown action cannot stamp true poison into mask");});
   Test("swarm-native-received-attack-expiry",()=>{var r=Start("shaman");Commit(r,Offer(r,K.FeignSwarm));Scope(r,"BoostAction",()=>NativeFeignSupportEffects.Removed(r.T,UnitEffect.Swift));Check(!Row(r).Appearance!.Effects.Contains("Swift")&&r.T.effects.Count==0,"native clear event applies even without true buff");});
   Test("exhaustion-only-clears-native-defined-statuses",()=>{var r=Start();Edit(r,x=>x.NativeId==2?x with{Appearance=x.Appearance! with{Effects=new[]{"Boosted","DoubleReady","Swift"}}}:x);Scope(r,"BoostAction",()=>NativeFeignSupportEffects.AfterExhausted(r.T));Check(Row(r).Appearance!.Effects.SequenceEqual(new[]{"Swift"}),"native MakeExhauseted clears2/7, not6");});
   Test("foreign-state-status-event-ignored",()=>{var r=Start();var other=new GameState();NativeFeignSupportEffects.BeforeScope(other,typeof(BoostAction).GetMethod("Execute")!,out var s);NativeFeignSupportEffects.Added(r.T,UnitEffect.Poisoned);NativeFeignSupportEffects.FinishScope(null,s);Check(Row(r).Appearance!.Effects.Length==0,"unbound scope cannot touch live frame");});
   Test("native-failed-action-no-apparent-event",()=>{var r=Start();NativeFeignSupportEffects.BeforeScope(r.S,typeof(BoostAction).GetMethod("Execute")!,out var s);NativeFeignSupportEffects.Added(r.T,UnitEffect.Poisoned);var e=new Exception("native failed");Check(ReferenceEquals(e,NativeFeignSupportEffects.FinishScope(e,s))&&Row(r).Appearance!.Effects.Length==0,"failed event discarded");});
   Test("endturn-queues-until-owner-restored",()=>{var r=Start();Edit(r,x=>x.NativeId==2?x with{Appearance=x.Appearance! with{Effects=new[]{"Frozen","Petrified","Swift"}}}:x);NativeFeignSupportEffects.BeforeScope(r.S,typeof(EndTurnCommand).GetMethod("Execute")!,out var s);NativeFeignSupportEffects.Removed(r.T,UnitEffect.Frozen);NativeFeignSupportEffects.Removed(r.T,UnitEffect.Petrified);NativeFeignSupportEffects.FinishScope(null,s);Check(Row(r).Appearance!.Effects.Contains("Frozen"),"pending owner scope cannot publish");NativeFeignSupportEffects.Flush(r.S);Check(Row(r).Appearance!.Effects.SequenceEqual(new[]{"Swift"}),"native turn clears freeze, never fabricates shorter Swarm timer");});
   foreach(bool failed in new[]{false,true})Test("explicit-endturn-boundary-"+failed,()=>{var r=Start();Edit(r,x=>x.NativeId==2?x with{Appearance=x.Appearance! with{Effects=new[]{"Frozen"}}}:x);var scope=NativeFeignSupportEffects.BeginEndTurn(r.S);NativeFeignSupportEffects.Removed(r.T,UnitEffect.Frozen);Check(Row(r).Appearance!.Effects.Contains("Frozen"),"owner substitution window has no publication");Exception? failure=failed?new Exception("turn failed"):null;Check(ReferenceEquals(failure,NativeFeignSupportEffects.EndTurnFinished(scope,failure)),"native failure retained");Check(Row(r).Appearance!.Effects.Contains("Frozen")==failed,"only successful restored-owner boundary publishes");});
   foreach(string condition in new[]{"normal","boost","double-callback","throw","uncommitted","invalid","hidden","no-map","state-change","replay","spectator","not-viewing","invisible-unit","not-visible-unit","stale-unit","client-change"})Test("reaction-"+condition,()=>{var r=Start(condition=="boost"?"shaman":"mindbender");var i=Offer(r,condition=="boost"?K.FeignSwarm:K.FeignHeal);if(condition!="uncommitted")Commit(r,i);var reaction=new BuildReaction{action=new BuildAction{Intent=i,Invalid=condition=="invalid"}};int calls=0;var callback=new Il2CppSystem.Action(()=>calls++);if(condition=="double-callback")VisualEvents.DoubleCallback=true;if(condition=="throw")VisualEvents.Throw=true;if(condition=="hidden")foreach(var tile in MapRenderer.Current!.Tiles.Values)tile.IsHidden=true;if(condition=="no-map")MapRenderer.Current=null;if(condition is "state-change" or "client-change")VisualEvents.Delay=true;
    if(condition=="replay")GameManager.Client.IsReplay=true;if(condition=="spectator")GameManager.Client.IsSpectating=true;if(condition=="not-viewing")GameManager.Viewing=false;
